INSERT INTO "public"."g2p_register_schemas" ("register_id","deduplicate_schema","search_result_schema","filter_schema") VALUES
-- Individual
-- Search-result fields are ordered for at-a-glance recognition of an
-- individual: ID first, then full name (most readable), then masked
-- foundational ID (audit/verification anchor), then person-level
-- demographics (gender, DOB, marital status), then citizenship and a
-- locality clue (address line 1) so officers can disambiguate quickly.
('a0000000-0000-4000-8000-000000000001',
 '[{"field_name": "first_name", "match_type": "fuzzy", "weight": 0.25}, {"field_name": "last_name", "match_type": "fuzzy", "weight": 0.25}, {"field_name": "birth_date", "match_type": "exact", "weight": 0.2}, {"field_name": "foundational_id", "match_type": "exact", "weight": 0.3}]',
 '[{"field_name": "functional_record_id", "display_label": "Individual ID", "order": 1}, {"field_name": "full_name", "display_label": "Full Name", "order": 2}, {"field_name": "foundational_id_masked", "display_label": "Foundational ID", "order": 3}, {"field_name": "gender", "display_label": "Gender", "order": 4}, {"field_name": "birth_date", "display_label": "Birth Date", "order": 5}, {"field_name": "marital_status", "display_label": "Marital Status", "order": 6}, {"field_name": "citizenship_category", "display_label": "Citizenship", "order": 7}, {"field_name": "address_line_1", "display_label": "Address", "order": 8}]',
 '[{"field_name": "full_name", "display_label": "Full Name", "filter_type": "text", "order": 1, "allowed_operators": ["eq", "contains"]}, {"field_name": "first_name", "display_label": "First Name", "filter_type": "text", "order": 2, "allowed_operators": ["eq", "contains"]}, {"field_name": "last_name", "display_label": "Last Name", "filter_type": "text", "order": 3, "allowed_operators": ["eq", "contains"]}, {"field_name": "gender", "display_label": "Gender", "filter_type": "dropdown", "order": 4, "allowed_operators": ["eq", "in"], "options_source": [{"value": "MALE", "label": "MALE"}, {"value": "FEMALE", "label": "FEMALE"}, {"value": "OTHERS", "label": "OTHERS"}, {"value": "UNKNOWN", "label": "UNKNOWN"}]}, {"field_name": "birth_date", "display_label": "Birthdate", "filter_type": "date_range", "order": 5, "allowed_operators": ["eq", "gt", "gte", "lt", "lte", "between"]}, {"field_name": "marital_status", "display_label": "Marital Status", "filter_type": "dropdown", "order": 6, "allowed_operators": ["eq", "in"], "options_source": [{"value": "SINGLE", "label": "SINGLE"}, {"value": "MARRIED", "label": "MARRIED"}, {"value": "DIVORCED", "label": "DIVORCED"}, {"value": "WIDOWED", "label": "WIDOWED"}, {"value": "SEPARATED", "label": "SEPARATED"}, {"value": "UNKNOWN", "label": "UNKNOWN"}]}, {"field_name": "citizenship_category", "display_label": "Citizenship", "filter_type": "dropdown", "order": 7, "allowed_operators": ["eq", "in"], "options_source": [{"value": "CITIZEN", "label": "CITIZEN"}, {"value": "REFUGEE", "label": "REFUGEE"}, {"value": "IDP", "label": "IDP"}, {"value": "RETURNEE", "label": "RETURNEE"}, {"value": "RESIDENT", "label": "RESIDENT"}]}, {"field_name": "disability_status", "display_label": "Disability", "filter_type": "dropdown", "order": 8, "allowed_operators": ["eq"], "options_source": [{"value": "YES", "label": "YES"}, {"value": "NO", "label": "NO"}, {"value": "UNKNOWN", "label": "UNKNOWN"}]}, {"field_name": "record_status", "display_label": "Record Status", "filter_type": "dropdown", "order": 9, "allowed_operators": ["eq", "in"], "options_source": [{"value": "ACTIVE", "label": "ACTIVE"}, {"value": "INACTIVE", "label": "INACTIVE"}, {"value": "ARCHIVED", "label": "ARCHIVED"}]}]'),

-- Household
-- Search-result fields: ID, head, household composition (size + headship type),
-- then dwelling and a locality clue. No country-specific admin-hierarchy
-- columns (region/woreda/kebele) — generic G2PGeo `address_line_1` is used.
('a0000000-0000-4000-8000-000000000002',
 '[{"field_name": "household_head_name", "match_type": "fuzzy", "weight": 0.5}, {"field_name": "address_line_1", "match_type": "fuzzy", "weight": 0.3}, {"field_name": "size_total", "match_type": "exact", "weight": 0.2}]',
 '[{"field_name": "functional_record_id", "display_label": "Household ID", "order": 1}, {"field_name": "household_head_name", "display_label": "Head", "order": 2}, {"field_name": "headship_type", "display_label": "Headship", "order": 3}, {"field_name": "size_total", "display_label": "Members", "order": 4}, {"field_name": "dwelling_type", "display_label": "Dwelling", "order": 5}, {"field_name": "tenure_status", "display_label": "Tenure", "order": 6}, {"field_name": "address_line_1", "display_label": "Address", "order": 7}]',
 '[{"field_name": "household_head_name", "display_label": "Head", "filter_type": "text", "order": 1, "allowed_operators": ["eq", "contains"]}, {"field_name": "headship_type", "display_label": "Headship", "filter_type": "dropdown", "order": 2, "allowed_operators": ["eq", "in"], "options_source": [{"value": "MALE_HEADED", "label": "MALE_HEADED"}, {"value": "FEMALE_HEADED", "label": "FEMALE_HEADED"}, {"value": "CHILD_HEADED", "label": "CHILD_HEADED"}, {"value": "ELDERLY_HEADED", "label": "ELDERLY_HEADED"}, {"value": "DISABLED_HEADED", "label": "DISABLED_HEADED"}]}, {"field_name": "size_total", "display_label": "Total Size", "filter_type": "number", "order": 3, "allowed_operators": ["eq", "gt", "gte", "lt", "lte"]}, {"field_name": "dwelling_type", "display_label": "Dwelling", "filter_type": "dropdown", "order": 4, "allowed_operators": ["eq", "in"], "options_source": [{"value": "PERMANENT", "label": "PERMANENT"}, {"value": "SEMI_PERMANENT", "label": "SEMI_PERMANENT"}, {"value": "TEMPORARY", "label": "TEMPORARY"}]}, {"field_name": "tenure_status", "display_label": "Tenure", "filter_type": "dropdown", "order": 5, "allowed_operators": ["eq", "in"], "options_source": [{"value": "OWNED", "label": "OWNED"}, {"value": "RENTED", "label": "RENTED"}, {"value": "HOSTED", "label": "HOSTED"}, {"value": "TEMPORARY", "label": "TEMPORARY"}]}, {"field_name": "address_line_1", "display_label": "Address", "filter_type": "text", "order": 6, "allowed_operators": ["eq", "contains"]}]'),

