('b0000000-0000-4000-8000-000000000010',
 '[{"field_name": "program_name", "match_type": "fuzzy", "weight": 0.5}, {"field_name": "program_mnemonic", "match_type": "exact", "weight": 0.3}, {"field_name": "legacy_program_id", "match_type": "exact", "weight": 0.2}]',
 '[{"field_name": "functional_record_id", "display_label": "Participation ID", "order": 1}, {"field_name": "program_name", "display_label": "Programme", "order": 2}, {"field_name": "program_start_date", "display_label": "Start", "order": 3}, {"field_name": "program_exit_date", "display_label": "Exit", "order": 4}, {"field_name": "payment_channel_preference", "display_label": "Payment Channel", "order": 5}]',
